/**
 * Run with: npx ts-node src/database/seed.ts
 * Seeds the local dev database with the four supported exams and
 * a representative set of Karnataka engineering colleges.
 */
import fs from 'fs';
import path from 'path';
import mongoose from 'mongoose';
import * as bcrypt from 'bcrypt';

const MONGO_URI = process.env.MONGO_URI ?? 'mongodb://localhost:27017/career-compass-dev';

// Researched college images (see scripts/research-college-images.py) — same
// file the live-DB `POST /admin/colleges/import/images` endpoint reads
// (CollegeService.importCollegeImages). Merged in here too so a *fresh*
// `npx ts-node src/database/seed.ts` run comes with images already
// populated, without requiring a separate import step afterwards.
type ResearchedImage = {
  category: string; url: string; title: string; thumbnailUrl?: string | null; altText?: string;
  sourceUrl?: string; sourceName?: string; verificationStatus?: 'verified' | 'needs_review' | 'rejected'; isPrimary?: boolean;
};
function loadCollegeImages(): Map<string, ResearchedImage[]> {
  const candidates = [
    path.resolve(process.cwd(), 'data/college-images.json'),
    path.resolve(process.cwd(), 'apps/api/data/college-images.json'),
    path.resolve(__dirname, '../../data/college-images.json'),
  ];
  const found = candidates.find(p => fs.existsSync(p));
  if (!found) return new Map();
  const records: { collegeId: string; images: ResearchedImage[] }[] = JSON.parse(fs.readFileSync(found, 'utf8'));
  return new Map(records.filter(r => r.images.length > 0).map(r => [r.collegeId, r.images]));
}

function withResearchedImages(colleges: any[]): any[] {
  const imagesByCollegeId = loadCollegeImages();
  let merged = 0;
  const result = colleges.map(c => {
    const images = c.collegeId ? imagesByCollegeId.get(c.collegeId) : undefined;
    if (!images || (c.gallery && c.gallery.length > 0)) return c;
    merged++;
    const gallery = images.map((img, idx) => ({
      id: `img_${Date.now().toString(36)}_${idx}_${Math.random().toString(36).slice(2, 6)}`,
      category: img.category, url: img.url, title: img.title,
      thumbnailUrl: img.thumbnailUrl ?? null, altText: img.altText ?? `${c.name} — ${img.title}`,
      sourceUrl: img.sourceUrl ?? null, sourceName: img.sourceName ?? null,
      verificationStatus: img.verificationStatus ?? 'needs_review', isPrimary: !!img.isPrimary,
      displayOrder: idx, addedAt: new Date(),
    }));
    const primary = gallery.find(g => g.isPrimary && g.verificationStatus === 'verified');
    return { ...c, gallery, bannerImage: c.bannerImage || primary?.url || c.bannerImage };
  });
  console.log(`Merged researched images into ${merged}/${colleges.length} colleges`);
  return result;
}

